<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO | اعتماد الأعمال</title><style>:root{font-family:Tahoma,Arial,sans-serif;--navy:#1e315b;--red:#ce122d;--muted:#68758a}*{box-sizing:border-box}body{margin:0;background:#f7f9fc;color:#132137}.wrap{width:min(1050px,94%);margin:24px auto}.head{display:flex;align-items:center;gap:16px;margin-bottom:18px}.logo{width:110px;height:65px;object-fit:contain}.head a{margin-right:auto;color:var(--navy);font-weight:700;text-decoration:none}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.btn{border:0;border-radius:8px;padding:9px 13px;background:var(--navy);color:#fff;font-weight:700;cursor:pointer}.btn.red{background:var(--red)}textarea{width:100%;min-height:75px;padding:10px;border:1px solid #ccd5e2;border-radius:8px}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef3fa}.notice{background:#eaf8ef;color:#207a43;padding:10px;border-radius:9px;margin-bottom:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}.head{flex-wrap:wrap}}</style></head><body><main class="wrap"><div class="head"><img class="logo" src="{{ route('brand.logo') }}" alt="UNIFCO"><div><h1 style="margin:0;color:var(--navy)">اعتماد الأعمال المكتملة</h1><div style="color:var(--muted)">مراجعة واعتماد أو رفض أوامر العمل بعد إتمام الصيانة.</div></div><a href="{{ route('customer.portal') }}">العودة إلى البوابة</a></div>@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif<h2>بانتظار قرارك</h2><div class="grid">@forelse($pending as $w)<section class="card"><strong>{{ $w->work_order_no }}</strong><p>النوع: {{ $w->maintenance_type }}<br>تاريخ الإكمال: {{ $w->completed_at?->format('Y-m-d H:i') }}<br>التكلفة: {{ number_format((float)$w->total_cost,2) }} SAR</p><form method="POST" action="{{ route('customer.work-acceptance.decide',$w) }}">@csrf<textarea name="notes" placeholder="ملاحظات العميل"></textarea><div style="display:flex;gap:8px;margin-top:10px"><button class="btn" name="decision" value="ACCEPT">اعتماد</button><button class="btn red" name="decision" value="REJECT">رفض وطلب مراجعة</button></div></form></section>@empty<section class="card">لا توجد أعمال مكتملة بانتظار الاعتماد.</section>@endforelse</div><h2>سجل القرارات</h2>@forelse($history as $w)<section class="card"><strong>{{ $w->work_order_no }}</strong> <span class="pill">{{ $w->customer_accepted_at ? 'معتمد' : 'مرفوض' }}</span><p>{{ $w->customer_acceptance_notes ?: 'بدون ملاحظات' }}</p></section>@empty<section class="card">لا يوجد سجل قرارات بعد.</section>@endforelse</main></body></html>